//! 🧪️ Exact SELECT constructors cross original receiving and the central strict candidate.
use super::*;
fn contract()->serde_json::Value{serde_json::from_str(include_str!("🧪️tests/type-select-input.json")).unwrap()}
fn source(law:&serde_json::Value,name:&str)->Arc<IfcSnapshot>{let domain=law["domains"].as_array().unwrap().iter().find(|row|row["entity"]==name).unwrap();let lag=name=="IFCLAGTIME";let mut entities=vec![IfcEntity{id:1,name:name.into(),args:if lag{vec![IfcValue::Unset,IfcValue::Enum("WORKTIME".into())]}else{vec![IfcValue::Unset,IfcValue::Unset,IfcValue::Unset,IfcValue::Unset,IfcValue::Reference(7)]},complex:domain["ancestors"].as_array().unwrap().iter().map(|name|IfcComplexType{name:name.as_str().unwrap().into(),args:if name=="IFCSCHEDULINGTIME"{vec![IfcValue::String("original".into()),IfcValue::Enum("PREDICTED".into()),IfcValue::Unset]}else{Vec::new()}}).collect()}];if !lag{entities.extend([IfcEntity{id:7,name:"IFCPOLYLINE".into(),args:vec![IfcValue::Aggregate(vec![IfcValue::Reference(9),IfcValue::Reference(10)])],complex:Vec::new()},IfcEntity{id:9,name:"IFCCARTESIANPOINT".into(),args:vec![IfcValue::Aggregate(vec![IfcValue::Real(0.0),IfcValue::Real(0.0)])],complex:Vec::new()},IfcEntity{id:10,name:"IFCCARTESIANPOINT".into(),args:vec![IfcValue::Aggregate(vec![IfcValue::Real(1.0),IfcValue::Real(0.0)])],complex:Vec::new()}]);}Arc::new(IfcSnapshot{entities,..Default::default()})}
fn event(row:&serde_json::Value)->editing::SnapshotEditEvent{let value=if row["kind"]=="real"{serde_json::json!({"bits":row["raw"]})}else{row["raw"].clone()};editing::SnapshotEditEvent::SetValue{path:"/entities/0".into(),value:super::type_input_tests::raw(&serde_json::json!({"$ifcType":row["entity"],"$ifcInputs":[{"index":"0","value":{"kind":"typedValue","value":{"name":row["member"],"items":[{"kind":row["kind"],"value":value}]}}}]}))}}
fn set(root:&mut DslValue,path:&[String],value:&DslValue){if path.is_empty(){*root=value.clone();return;}let child=match root{DslValue::Object(fields)=>{let index=fields.iter().position(|(key,_)|key==&path[0]);if index.is_none()&&path.len()==1{fields.push((path[0].clone(),value.clone()));return;}let index=index.unwrap();&mut fields[index].1},DslValue::Array(values)=>&mut values[path[0].parse::<usize>().unwrap()],_=>panic!("closed fixture address")};set(child,&path[1..],value);}
struct AlternateProfile;
impl IfcDetailsProfile for AlternateProfile{
 type CandidateRules=();const MAXIMUM_ATTRIBUTES:usize=0;
 fn catalog()->&'static IfcCatalog{panic!("alternate profile must refuse before catalog access")}
 fn defined_type_expression(_: &str)->Option<&'static dyn IfcDetailsTypeMetadata>{panic!("alternate alias hook must not execute")}
 fn select_count(_: &str)->Option<usize>{panic!("alternate SELECT count must not execute")}
 fn select_member(_: &str,_:usize)->Option<&'static str>{panic!("alternate SELECT member must not execute")}
}
#[test]
fn original_select_profile_pins_each_new_hook_even_when_other_hook_identities_match(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();let row=&law["cases"][0];let snapshot=source(&law,row["entity"].as_str().unwrap());let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(row),&mut caller,&mut work,|input,caller,work|{let mut receiving=false;for _ in 0..1000000{if work.constituent_roster.receiving_primitives(){receiving=true;break;}assert!(!matches!(caller.work_turn(grant(),1,|cx|work.step(input,cx)).unwrap(),ArtifactCommandWorkStep::Complete(_)));}assert!(receiving);for hook in 3..6{let original=work.constituent_roster.profile_probe::<AlternateProfile>(hook);let metadata=work.constituent_roster.metadata();let command=work.original_event.as_ref().unwrap().to_value();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(grant(),1,|cx|{let before=cx.retained_progress();assert!(work.constituent_roster.advance::<AlternateProfile>(work.original_event.as_mut().unwrap(),&snapshot,&work.address,work.source.as_ref(),&mut work.parts_cursor,&mut work.parts,&mut work.pending,&mut work.value_cursor,&mut work.value,cx).is_err());assert_eq!(before,cx.retained_progress());Ok(())}));answer.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(metadata,work.constituent_roster.metadata());assert_eq!(command,work.original_event.as_ref().unwrap().to_value());work.constituent_roster.restore_profile_probe(original);}
  for _ in 0..1000000{if work.pending.is_some()&&work.constituent_roster.type_admission().is_some(){break;}assert!(!matches!(caller.work_turn(grant(),1,|cx|work.step(input,cx)).unwrap(),ArtifactCommandWorkStep::Complete(_)));}assert!(work.constituent_roster.type_admission().is_some());for hook in 3..6{let original=work.constituent_roster.profile_probe::<AlternateProfile>(hook);let metadata=work.constituent_roster.metadata();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(grant(),1,|cx|{let before=cx.retained_progress();assert!(work.constituent_roster.type_admission().unwrap().validate::<AlternateProfile>(work.original_event.as_ref().unwrap(),&snapshot,&work.address,work.pending.as_deref().unwrap(),cx).is_err());assert_eq!(before,cx.retained_progress());Ok(())}));answer.unwrap();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(metadata,work.constituent_roster.metadata());work.constituent_roster.restore_profile_probe(original);}super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();
}
#[test]
fn original_select_kind_cursor_visits_complete_released_member_domains_without_allocating(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 for domain in contract()["domains"].as_array().unwrap(){let name=domain["entity"].as_str().unwrap();let attribute=DetailsTestProfile::normalization_attribute(name,0,true).unwrap().unwrap();let mut cursor=super::super::super::type_input_kind::Cursor::default();let mut complete=None;for _ in 0..1024{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance::<DetailsTestProfile>(attribute.type_expr));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(kind)=answer.unwrap(){complete=Some(kind);break;}}assert_eq!(complete,Some(super::super::super::type_input_kind::Kind::Select));assert_eq!(cursor.domain(),domain["select"].as_str());assert_eq!(DetailsTestProfile::select_count(cursor.domain().unwrap()),Some(domain["members"].as_array().unwrap().len()));}
}
#[test]
fn original_select_constructors_match_neutral_domains_exact_payload_and_central_inverse(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law,row["entity"].as_str().unwrap());let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(row),&mut caller,&mut work,|input,caller,work|{let mut output=None;for turn in 0..1000000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Ok(ArtifactCommandWorkStep::Complete(emit))=>{output=Some(Ok(emit));break;},Err(error)=>{output=Some(Err(error));break;},_=>{}}assert!(turn<999999);}let output=output.unwrap();assert_eq!(output.is_ok(),row["admitted"].as_bool().unwrap(),"{}",row["id"]);if let Ok(emit)=output{assert_eq!(emit.artifact_mutations.len(),1);assert!(matches!(emit.artifact_mutations[0],IfcMutation::SetEntityArg(_)));let mutation=&emit.artifact_mutations[0];let inverse=mutation.inverse(&snapshot).unwrap();let mut next=protocol::apply_diff_cold(mutation.diff(&snapshot).diff(),&snapshot).unwrap();let child=if row["kind"]=="real"{IfcValue::Real(f64::from_bits(row["raw"].as_str().unwrap().parse().unwrap()))}else{IfcValue::String(row["raw"].as_str().unwrap().into())};let expected=IfcValue::TypedValue(IfcTypedValue{name:row["member"].as_str().unwrap().into(),items:vec![child]});assert!(ifc_arguments_identical(&next.entities[0].args[..1],&[expected]));assert!(ifc_arguments_identical(&next.entities[0].args[1..],&snapshot.entities[0].args[1..]));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args,&snapshot.entities[0].args));}super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();}
}
#[test]
fn original_select_receiving_denies_axes_and_cancels_without_publishing_partial_constructor(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();let row=&law["cases"][0];let snapshot=source(&law,row["entity"].as_str().unwrap());let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(row),&mut caller,&mut work,|input,caller,work|{let mut reached=false;for _ in 0..1000000{if work.constituent_roster.receiving_primitives(){reached=true;let demand=work.work_demands(input,4096).unwrap();for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4=>denied.maximum_depth=0,5=>fuel=0,_=>continue};let state=work.constituent_roster.metadata();caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||work.step(input,cx));assert!(!matches!(answer?,ArtifactCommandWorkStep::Complete(_)));assert_eq!(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();assert_eq!(state,work.constituent_roster.metadata());}}if work.domain_validated{break;}assert!(!matches!(caller.work_turn(grant(),1,|cx|work.step(input,cx)).unwrap(),ArtifactCommandWorkStep::Complete(_)));}assert!(reached);caller.cancel().cancel_now();assert!(caller.work_turn(grant(),1,|cx|work.step(input,cx)).is_err());super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();
}
#[test]
fn original_select_guidance_keeps_discriminator_and_scalar_editable_without_default_children(){
 use semio_framework_plugin::action_staging::*;use semio_framework_plugin_decl_staged_form::*;
 type Guidance=super::super::super::type_guidance::IfcTypeInputSourceWork<DetailsTestProfile>;
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){for mode in 0..3{let snapshot=source(&law,row["entity"].as_str().unwrap());let editing::SnapshotEditEvent::SetValue{path,value}=event(row)else{unreachable!()};let mut value=value;if mode==0{let DslValue::Object(fields)=&mut value else{unreachable!()};fields.iter_mut().find(|(key,_)|key=="$ifcInputs").unwrap().1=DslValue::Array(Vec::new());}else if mode==1{let DslValue::Object(fields)=&mut value else{unreachable!()};let DslValue::Array(rows)=&mut fields.iter_mut().find(|(key,_)|key=="$ifcInputs").unwrap().1 else{unreachable!()};let DslValue::Object(fields)=&mut rows[0]else{unreachable!()};let DslValue::Object(fields)=&mut fields.iter_mut().find(|(key,_)|key=="value").unwrap().1 else{unreachable!()};let DslValue::Object(fields)=&mut fields.iter_mut().find(|(key,_)|key=="value").unwrap().1 else{unreachable!()};fields.iter_mut().find(|(key,_)|key=="items").unwrap().1=DslValue::Array(Vec::new());}
  let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"select-original".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::De,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:None});let original_args=donor.as_ref().unwrap().args.clone();let mut caller=OriginalWorkFixture::new();let mut guide=Some(Guidance::default());let mut output=None;assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());assert!(donor.is_none());for turn in 0..1000000{let demand=guide.as_ref().unwrap().demands().unwrap();let(repeated,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||guide.as_ref().unwrap().demands());assert_eq!(repeated.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=guide.as_mut().unwrap().advance(&snapshot,[0;32],cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());let prepared=output.as_ref().unwrap();assert_eq!(prepared.status().ready,mode==2&&row["admitted"].as_bool().unwrap());assert_eq!(prepared.controls(),if mode==0{1}else{2});let discriminator=prepared.control(0).unwrap();let StagedScalarKind::Choice{value,choices}=discriminator.scalar.kind else{panic!("declared SELECT member")};assert_eq!(value,if mode==0{""}else{row["member"].as_str().unwrap()});assert_eq!(choices.len(),2);let StagedBodyBinding::Action(binding)=discriminator.binding.unwrap()else{panic!("original discriminator binding")};let selected=DslValue::String(row["member"].as_str().unwrap().into());let mut changed=original_args.clone();for edit in binding.plan(prepared.status(),Some(&selected)).unwrap(){let StagedFormBorrowedEdit::Set{path,value}=edit else{panic!("closed SELECT set binding")};set(&mut changed,path,value);}let payload=changed.get("value").unwrap().get("$ifcInputs").unwrap();let DslValue::Array(rows)=payload else{panic!("sorted caller rows")};assert_eq!(rows.len(),1);assert_eq!(rows[0].get("index").and_then(DslValue::as_str),Some("0"));let typed=rows[0].get("value").unwrap().get("value").unwrap();let(name,items)=super::super::super::type_input::typed_constructor(typed).unwrap();assert_eq!(name,row["member"].as_str().unwrap());assert_eq!(items.len(),usize::from(mode==2));if mode>0{let scalar=prepared.control(1).unwrap();let StagedScalarKind::Text{value}=scalar.scalar.kind else{panic!("typed selected scalar")};assert_eq!(value,if mode==1{""}else{row["raw"].as_str().unwrap()});let StagedBodyBinding::Action(binding)=scalar.binding.unwrap()else{panic!("original selected scalar binding")};assert!(binding.edits.iter().any(|edit|matches!(edit,StagedFormBindingEdit::Text{path}if path.iter().any(|part|part=="items"))));let input=DslValue::String(row["raw"].as_str().unwrap().into());let mut changed=original_args.clone();for edit in binding.plan(prepared.status(),Some(&input)).unwrap(){let StagedFormBorrowedEdit::Set{path,value}=edit else{panic!("closed selected scalar set")};set(&mut changed,path,value);}let DslValue::Array(rows)=changed.get("value").unwrap().get("$ifcInputs").unwrap()else{panic!("caller rows")};let(_,items)=super::super::super::type_input::typed_constructor(rows[0].get("value").unwrap().get("value").unwrap()).unwrap();assert_eq!(items.len(),1);let value=items[0].get("value").unwrap();assert_eq!(value.as_str().or_else(||value.get("bits").and_then(DslValue::as_str)),row["raw"].as_str());}caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();}}
}
